local offline_http={}
local offline_notified={}
local function local_request(method,url,options,callback)
    if type(options)=='function' then callback=options end
    local asset=offline_asset_files[url]
    if method=='GET' and asset then
        if callback then client.delay_call(0,callback,true,{status=200,body=asset.body,headers={}}) end
        return
    end
    if not offline_notified[url] then
        offline_notified[url]=true
        client.log('[rinnegan offline] Network feature unavailable: '..method..' '..url)
    end
    if callback then client.delay_call(0,callback,false,{status=0,body='',headers={},error='offline mode'}) end
end
function offline_http.get(url,options,callback)return local_request('GET',url,options,callback)end
function offline_http.post(url,options,callback)return local_request('POST',url,options,callback)end

local function install_amnesia_advertising()
    local brand = 'AMNESIA.plus'
    local tagline = 'buy the best lua'
    local invite = 'discord.gg/25WdHEmwa'
    local invite_url = 'https://' .. invite
    local headline = 'лучший дс сервер с ликами - ' .. invite
    local clipboard = require('gamesense/clipboard')
    local started = globals.realtime()
    local accent = {190, 148, 255}
    local menu_labels = {}

    local function announce()
        client.color_log(accent[1], accent[2], accent[3], '[AMNESIA.plus] ', tagline)
        client.color_log(230, 230, 240, headline)
        client.color_log(accent[1], accent[2], accent[3], invite)
    end

    local function join_discord()
        panorama.open('CSGOHud').SteamOverlayAPI.OpenExternalBrowserURL(invite_url)
    end

    local function copy_invite()
        clipboard.set(invite_url)
        client.color_log(accent[1], accent[2], accent[3], '[AMNESIA.plus] ', invite)
    end

    for _, container in ipairs({'Anti-aimbot angles', 'Fake lag', 'Other'}) do
        local suffix = '\nAMNESIA_' .. container
        menu_labels[#menu_labels + 1] = ui.new_label('AA', container, '\aBE94FFFF' .. brand .. suffix)
        menu_labels[#menu_labels + 1] = ui.new_label('AA', container, '\aFFFFFFFF' .. tagline .. suffix)
        menu_labels[#menu_labels + 1] = ui.new_label('AA', container, 'лучший дс сервер с ликами' .. suffix)
        menu_labels[#menu_labels + 1] = ui.new_label('AA', container, '\aBE94FFFF' .. invite .. suffix)
        menu_labels[#menu_labels + 1] = ui.new_button('AA', container, 'Discord: ' .. invite .. suffix, join_discord)
        menu_labels[#menu_labels + 1] = ui.new_button('AA', container, 'AMNESIA.plus | Copy invite' .. suffix, copy_invite)
    end

    local function text(x, y, alpha, flags, value, colored)
        if colored then
            renderer.text(x, y, accent[1], accent[2], accent[3], alpha, flags, 0, value)
        else
            renderer.text(x, y, 244, 244, 250, alpha, flags, 0, value)
        end
    end

    local function card(x, y, width, height, alpha)
        renderer.rectangle(x, y, width, height, 16, 14, 24, math.floor(alpha * 0.86))
        renderer.rectangle(x, y, width, 2, accent[1], accent[2], accent[3], alpha)
    end

    local function paint_advertising()
        local screen_width, screen_height = client.screen_size()
        local title_width = renderer.measure_text('', headline)
        local width = math.min(screen_width - 32, math.max(360, title_width + 36))
        local center = screen_width / 2
        local left = math.floor(center - width / 2)

        card(left, 12, width, 65, 235)
        text(center, 20, 255, 'c+', brand, true)
        text(center, 37, 255, 'c', tagline)
        text(center, 54, 255, 'c', headline)

        card(left, screen_height - 43, width, 31, 210)
        text(center, screen_height - 33, 245, 'c', brand .. ' | ' .. invite, true)

        if globals.realtime() - started < 12 then
            local y = math.floor(screen_height * 0.20)
            card(left, y, width, 76, 245)
            text(center, y + 12, 255, 'c+', brand, true)
            text(center, y + 32, 255, 'c', tagline)
            text(center, y + 53, 255, 'c', headline)
        end

        if ui.is_menu_open() then
            local menu_x, menu_y = ui.menu_position()
            local menu_width = ui.menu_size()
            local panel_width = math.min(300, screen_width - 32)
            local x = math.max(16, math.min(menu_x + menu_width + 12, screen_width - panel_width - 16))
            local y = math.max(88, math.min(menu_y, screen_height - 154))
            card(x, y, panel_width, 106, 245)
            text(x + panel_width / 2, y + 12, 255, 'c+', brand, true)
            text(x + panel_width / 2, y + 33, 255, 'c', tagline)
            text(x + panel_width / 2, y + 57, 255, 'c', 'лучший дс сервер с ликами')
            text(x + panel_width / 2, y + 79, 255, 'c', invite, true)
        end
    end

    announce()
    client.set_event_callback('paint_ui', paint_advertising)
    client.set_event_callback('round_start', announce)
end

